//
// The session wrapper for TypeScript over @grpc/grpc-js and
// @grpc/proto-loader: load the .proto beside this file at runtime, take
// the service client it yields, and open a session here. protoc's typed
// stubs fit where a build step is welcome; this wrapper leans on the
// loader instead, so a host like an editor extension ships no native
// code and no generated stubs. Load with keepCase: true, longs: String,
// and oneofs: true: the field names keep the wire's own snake_case, and
// every 64 bit integer, the instance id and the hash first among them,
// crosses as a decimal string, which is how the interfaces below spell
// them. The syntax stays inside the erasable set, so node runs this
// file directly under type stripping, no compiler in the loop.

// The shape of the call a session opens, the one surface the wrapper
// needs from grpc-js, spelled structurally so nothing is imported.
export interface SessionStream {
  on(event: "data", listener: (ev: unknown) => void): unknown;
  on(event: "error", listener: (err: Error) => void): unknown;
  cancel(): void;
}

// FlowShapeHash is the contract's shape hash, the same value the
// compiled module registers. Sending its decimal spelling as expected_hash
// pins the wire to this build; leaving the field unset skips the check.
export const FlowShapeHash: bigint = 0xd18339eb8215935an;

export interface FlowSignRequest {
  expected_hash?: string;  // a decimal uint64; the shape hash's toString() pins
}

export interface FlowResumeRequest {
  park_token: string;  // the resume key a park enabled server issued at sign
  expected_hash?: string;  // a decimal uint64; the shape hash's toString() pins
}

export interface FlowSigned {
  instance_id: string;
  shape_hash: string;
  signed_at: string;
  park_token: string;  // empty when the server runs without a park store
}

// FlowSession holds a signed instance open. The instance lives
// exactly as long as this handle: close ends the stream, and the server
// breaks and drops the instance.
export interface FlowSession {
  signed: FlowSigned;
  close(): void;
}

// openFlowSession signs the contract and holds the session stream.
// The signature is read off the stream before the promise settles, so the
// caller holds a live, addressable instance or an error, never a maybe.
export function openFlowSession(
  client: { Session(req: FlowSignRequest): SessionStream },
  req: FlowSignRequest,
): Promise<FlowSession> {
  return new Promise((resolve, reject) => {
    const stream = client.Session(req);
    let opened = false;
    stream.on("data", (ev) => {
      if (opened) { return; }
      const signed = (ev as { signed?: FlowSigned }).signed;
      if (!signed) {
        stream.cancel();
        reject(new Error("the session stream opened without the signature"));
        return;
      }
      opened = true;
      resolve({ signed, close: () => stream.cancel() });
    });
    stream.on("error", (err) => {
      // After the signature the stream's end is the session's end, the
      // cancel the close asked for; before it, the sign itself refused.
      if (!opened) { reject(err); }
    });
  });
}

// resumeFlowSession stands a parked instance back up and holds its new
// session stream, the same handle open answers; close is once again the
// ending.
export function resumeFlowSession(
  client: { Resume(req: FlowResumeRequest): SessionStream },
  req: FlowResumeRequest,
): Promise<FlowSession> {
  return new Promise((resolve, reject) => {
    const stream = client.Resume(req);
    let opened = false;
    stream.on("data", (ev) => {
      if (opened) { return; }
      const signed = (ev as { signed?: FlowSigned }).signed;
      if (!signed) {
        stream.cancel();
        reject(new Error("the session stream opened without the signature"));
        return;
      }
      opened = true;
      resolve({ signed, close: () => stream.cancel() });
    });
    stream.on("error", (err) => {
      if (!opened) { reject(err); }
    });
  });
}

// signalFlowReady hands the ready signal to the session's instance. The
// promise settles once the server answered, and a refused delivery, an
// early one or one past its deadline, rejects with the call's error.
export function signalFlowReady(
  client: { SignalReady(req: object, done: (err: Error | null) => void): unknown },
  session: FlowSession,
  fields: { value: string; },
): Promise<void> {
  return new Promise((resolve, reject) => {
    const req = { instance_id: session.signed.instance_id, ...fields };
    client.SignalReady(req, (err) => {
      if (err) { reject(err); } else { resolve(); }
    });
  });
}

// getFlowCourse reads where the session's instance's course stands.
// state is the CourseState number, status the GeasStatus that halted it,
// and wait_due_ms the decimal runtime clock time its wait falls due, "0"
// when nothing is due. It never waits on the course.
export function getFlowCourse(
  client: { GetCourse(req: object, done: (err: Error | null, reply?: CourseReply) => void): unknown },
  session: FlowSession,
): Promise<CourseReply> {
  return new Promise((resolve, reject) => {
    client.GetCourse({ instance_id: session.signed.instance_id }, (err, reply) => {
      if (err || !reply) { reject(err ?? new Error("GetCourse answered nothing")); } else { resolve(reply); }
    });
  });
}

// What GetCourse answers, the CourseReply message as the loader hands it.
export interface CourseReply {
  state: number;
  step: number;
  status: number;
  wait_due_ms: string;
}
